//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::{
    arena::NodeId,
    context::{Context, DelimiterBottom, NodeKind},
};
use serde::Deserialize;
use serde_json::{Value, json};
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Operation {
    kind: String,
    #[serde(default, rename = "ID")]
    id: usize,
    bottom: Option<usize>,
    #[serde(default)]
    typed_nil: bool,
}
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    nodes: Vec<NodeKind>,
    parents: Vec<Option<usize>>,
    operations: Vec<Operation>,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
fn snapshot(c: &Context) -> Value {
    json!({"nodes":c.arena.nodes(),"first_delimiter":c.first_delimiter,"last_delimiter":c.last_delimiter})
}
#[test]
fn pinned_goldmark_delimiter_context() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/context.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.into_iter().zip(f.results).enumerate() {
        let mut c = Context::default();
        for node in q.nodes {
            c.arena.insert(node);
        }
        for (id, parent) in q.parents.into_iter().enumerate() {
            if let Some(parent) = parent {
                c.arena.append_child(NodeId(parent), NodeId(id));
            }
            if matches!(c.arena.node(NodeId(id)).data, NodeKind::Delimiter(_)) {
                c.push_delimiter(NodeId(id));
            }
        }
        let mut snapshots = vec![snapshot(&c)];
        for op in q.operations {
            match op.kind.as_str() {
                "process" => c.process_delimiters_with_bottom(if op.typed_nil {
                    DelimiterBottom::TypedNil
                } else {
                    op.bottom.map_or(DelimiterBottom::Absent, |id| {
                        DelimiterBottom::Node(NodeId(id))
                    })
                }),
                "remove" => c.remove_delimiter(NodeId(op.id)),
                "clear" => c.clear_delimiters(op.bottom.map(NodeId)),
                _ => panic!("unknown operation"),
            }
            snapshots.push(snapshot(&c));
        }
        assert_eq!(json!(snapshots), expected, "case {i}");
    }
}
